<style>
.review-tabs{display:flex;gap:10px;margin:24px 0}.review-tabs a,.print-btn{border:1px solid rgba(var(--overlay-rgb),.15);border-radius:999px;padding:11px 18px;color:var(--cream);text-decoration:none;background:transparent}.review-tabs a.active,.print-btn{background:#a5be91;color:#132116}.review-table{display:grid;gap:12px}.review-row{padding:17px 18px;border:1px solid rgba(var(--overlay-rgb),.08);border-radius:14px;background:rgba(var(--overlay-rgb),.025)}.review-row-head{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;color:var(--gold);font-size:.8rem}.review-row-stars{color:#e6b647;letter-spacing:.08em;margin-top:7px}.review-row p{color:rgba(var(--cream-rgb),.76);line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}.review-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.review-actions button{border:0;border-radius:8px;padding:8px 12px;cursor:pointer;font:inherit}.act-hide{background:#69521c;color:#fff}.act-remove{background:#612c24;color:#fff}.act-keep,.act-dismiss{background:#29432e;color:#fff}.report-reason{color:#efc16a;font-weight:700}.report-status{border-radius:999px;padding:3px 9px;background:#69521c;color:#fff;font-size:.75rem}.period-select{background:var(--sidebar);color:var(--cream);border:1px solid rgba(var(--overlay-rgb),.12);border-radius:999px;padding:9px 14px}.print-toolbar{display:flex;justify-content:flex-end;margin:0 0 14px}.report-detail{color:rgba(var(--cream-rgb),.65)}
