chars($adminRole) ?></div></div></div><a href="<?= BASE_URL ?>/auth/auth.php?action=logout" class="logout-link"><i data-lucide="log-out" class="lucide"></i> Log Out</a></div></aside>
<button class="hamburger-btn" type="button" onclick="document.getElementById('sidebar').classList.toggle('open')"><i data-lucide="menu" class="lucide"></i></button><div class="main-content"><div class="dash-wrapper"><div class="admin-site-switch-row"><a class="admin-site-switch" href="<?= BASE_URL ?>/index.php"><i data-lucide="external-link" class="lucide"></i> View user site</a></div>
<header class="page-header"><div><div class="section-label">Tourism Insights</div><h1><?= $tab === 'reports' ? 'Review ' : 'Ratings <em>&amp; Reviews</em>' ?><?= $tab === 'reports' ? '<em>Reports</em>' : '' ?></h1><p><?= $tab === 'reports' ? 'Review visitor reports and decide whether the comment should stay visible.' : 'Visitor feedback, rating trends, and recent comments.' ?></p></div></header>
<nav class="review-tabs" aria-label="Review administration"><a class="<?= $tab==='ratings'?'active':'' ?>" href="?tab=ratings">Ratings &amp; Reviews</a><a class="<?= $tab==='reports'?'active':'' ?>" href="?tab=reports">Reports<?= $pendingReports ? ' ('.$pendingReports.')' : '' ?></a></nav>
<?php if($tab==='ratings'): ?><div class="print-toolbar"><button class="print-btn" type="button" onclick="window.print()">Print analytics</button></div>
<div class="kpi-grid"><div class="kpi-card accent-gold"><div class="kpi-icon"><i data-lucide="star" class="lucide"></i></div><div class="kpi-num"><?= number_format((int)$summary['total']) ?></div><div class="kpi-label">Reviews</div><div class="kpi-change"><?= htmlspecialchars($periodLabel) ?></div></div><div class="kpi-card accent-clay"><div class="kpi-icon"><i data-lucide="message-square-text" class="lucide"></i></div><div class="kpi-num"><?= (int)$summary['total'] ? number_format((float)$summary['average_rating'],1).' / 5' : '—' ?></div><div class="kpi-label">Average Rating</div><div class="kpi-change">Visible submitted reviews</div></div><div class="kpi-card accent-green"><div class="kpi-icon"><i data-lucide="layers" class="lucide"></i></div><div class="kpi-num"><?= (int)$summary['categories'] ?></div><div class="kpi-label">Reviewed Categories</div><div class="kpi-change">Types with visitor feedback</div></div></div>
<div class="charts-2col"><div class="chart-box"><h4>Star Rating Distribution</h4><?php foreach([5,4,3,2,1] as $star): ?><div class="bar-row"><span class="bar-name"><?= $star ?> stars</span><div class="bar-track"><div class="bar-fill" style="width:<?= (int)round($ratingCounts[$star]/$ratingMax*100) ?>%"></div></div><span class="bar-pct"><?= $ratingCounts[$star] ?></span></div><?php endforeach ?></div><div class="chart-box"><h4>Ratings by Category</h4><?php if(!$typeStats): ?><div class="chart-empty"><div class="chart-empty-title">No reviews yet</div></div><?php else: foreach($typeStats as $row): ?><div class="bar-row"><span class="bar-name"><?= htmlspecialchars($categoryLabels[$row['item_type']]??ucfirst($row['item_type'])) ?></span><div class="bar-track"><div class="bar-fill" style="width:<?= (int)round((float)$row['average_rating']/5*100) ?>%"></div></div><span class="bar-pct"><?= number_format((float)$row['average_rating'],1) ?> · <?= (int)$row['review_count'] ?></span></div><?php endforeach; endif ?></div></div>
<section class="chart-box"><h4>Visitor Comments <span class="review-count">Up to 200 latest visible reviews · All time</span></h4><?php if(!$reviews): ?><div class="chart-empty"><div class="chart-empty-title">No reviews yet</div></div><?php else: ?><div class="review-table"><?php foreach($reviews as $r): ?><article class="review-row"><div class="review-row-head"><span><?= htmlspecialchars($r['item_name']) ?> · <?= htmlspecialchars($categoryLabels[$r['item_type']]??ucfirst($r['item_type'])) ?></span><span><?= htmlspecialchars($r['display_name']) ?> · <?= htmlspecialchars(date('M j, Y g:i A',strtotime($r['created_at']))) ?></span></div><div class="review-row-stars"><?= str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']) ?></div><p><?= htmlspecialchars($r['review_text']) ?></p></article><?php endforeach ?></div><?php endif ?></section>
<?php else: ?><div class="print-toolbar"><button class="print-btn" type="button" onclick="window.print()">Print reports</button></div><?php if(!$reports): ?><section class="chart-box"><div class="chart-empty"><div class="chart-empty-title">No reports have been submitted</div></div></section><?php else: ?><div class="review-table"><?php foreach($reports as $r): ?><article class="review-row"><div class="review-row-head"><span><?= htmlspecialchars($r['item_name']) ?> · <?= htmlspecialchars($categoryLabels[$r['item_type']]??ucfirst($r['item_type'])) ?> · <?= htmlspecialchars($r['display_name']) ?></span><span><?= htmlspecialchars(date('M j, Y g:i A',strtotime($r['reported_at']))) ?> · Reporter #<?= (int)$r['reporter_id'] ?> · <span class="report-status"><?= htmlspecialchars(ucfirst($r['report_status'])) ?></span></span></div><div class="review-row-stars"><?= str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']) ?> · Report: <span class="report-reason"><?= htmlspecialchars(ucwords(str_replace('_',' ',$r['reason_code']))) ?></span></div><p><?= htmlspecialchars($r['review_text']) ?></p><?php if($r['report_details']!==''): ?><p class="report-detail"><strong>Report details:</strong> <?= htmlspecialchars($r['report_details']) ?></p><?php endif ?><?php if($r['report_status']==='pending'): ?><div class="review-actions"><form method="post"><?= csrf_field() ?><input type="hidden" name="review_id" value="<?= (int)$r['review_id'] ?>"><button class="act-keep" name="moderation_action" value="keep">Keep review</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="review_id" value="<?= (int)$r['review_id'] ?>"><button class="act-hide" name="moderation_action" value="hide">Hide review</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="review_id" value="<?= (int)$r['review_id'] ?>"><button class="act-remove" name="moderation_action" value="remove" onclick="return confirm('Remove this review from public view?')">Remove review</button></form><form method="post"><?= csrf_field() ?><input type="hidden" name="report_id" value="<?= (int)$r['report_id'] ?>"><button class="act-dismiss" name="moderation_action" value="dismiss">Dismiss report</button></form></div><?php elseif($r['report_status']==='resolved'): ?><p class="report-detail">Moderation action: <?= htmlspecialchars(ucfirst($r['resolution_action']??'resolved')) ?></p><?php endif ?></article><?php endforeach ?></div><?php endif ?><?php endif ?>
</div></div><script src="../assets/js/admin-sidebar-collapse.js"></script><script>initSidebarCollapse();if(window.lucide)lucide.createIcons();</script></body></html>
